fn all_digits(text: Str) -> Bool {
  if text.is_empty() {
    return false
  }
  for c in text.chars() {
    if not "0123456789".contains(c) {
      return false
    }
  }
  return true
}

fn parse_amount(text: Str) -> Result[Int, Str] {
  if not all_digits(text) {
    return Err("bad op")
  }
  let n = text.to_int().unwrap_or(0)
  if n <= 0 {
    return Err("bad op")
  }
  return Ok(n)
}

pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
  var bal: Map[Str, Int] = Map {}
  for op in ops {
    let parts = op.split(" ")
    let verb = parts.get_or(0, "")
    let count = parts.len()
    if verb == "open" {
      if count != 2 {
        return Err("bad op")
      }
      let name = parts.get_or(1, "")
      if bal.has(name) {
        return Err("exists " + name)
      }
      bal = bal.set(name, 0)
    } else if verb == "dep" {
      if count != 3 {
        return Err("bad op")
      }
      let name = parts.get_or(1, "")
      let amount = parse_amount(parts.get_or(2, ""))?
      if not bal.has(name) {
        return Err("unknown " + name)
      }
      bal = bal.set(name, bal.get(name).unwrap_or(0) + amount)
    } else if verb == "wd" {
      if count != 3 {
        return Err("bad op")
      }
      let name = parts.get_or(1, "")
      let amount = parse_amount(parts.get_or(2, ""))?
      if not bal.has(name) {
        return Err("unknown " + name)
      }
      let have = bal.get(name).unwrap_or(0)
      if have < amount {
        return Err("insufficient " + name)
      }
      bal = bal.set(name, have - amount)
    } else if verb == "move" {
      if count != 4 {
        return Err("bad op")
      }
      let from_name = parts.get_or(1, "")
      let to_name = parts.get_or(2, "")
      let amount = parse_amount(parts.get_or(3, ""))?
      if not bal.has(from_name) {
        return Err("unknown " + from_name)
      }
      if not bal.has(to_name) {
        return Err("unknown " + to_name)
      }
      let have = bal.get(from_name).unwrap_or(0)
      if have < amount {
        return Err("insufficient " + from_name)
      }
      bal = bal.set(from_name, have - amount)
      bal = bal.set(to_name, bal.get(to_name).unwrap_or(0) + amount)
    } else {
      return Err("bad op")
    }
  }
  return Ok(bal)
}
